dest=root/'docs/validation/trajectory_review_k1_1_2026-11-01';dest.mkdir(exist_ok=False)
files={}
def bind(p):return {'sha256':hashlib.sha256(p.read_bytes()).hexdigest(),'bytes':p.stat().st_size}
def copy(p,name):
 q=dest/name;q.parent.mkdir(parents=True,exist_ok=True);shutil.copy2(p,q);assert bind(q)==bind(p);files[str(name)]={'source':str(p),**bind(q)}
for folder in sorted(eng.iterdir()):
 if folder.is_dir() and int(folder.name.split('_')[0][:3])>=17:
  for p in sorted(folder.rglob('*')):
   if p.is_file():copy(p,Path('commands')/folder.name/p.relative_to(folder))
for name in ['verify_report_numbers.py','verify_report_numbers_002.py','report_number_verification.json','obsidian_update.json']:
 copy(art/name,Path('checks')/name)
copy(Path('/tmp/k11_capture.py'),Path('sources/capture_command.py'))
copy(Path(__file__),Path('sources/publish_validation.py'))
known=[json.loads(p.read_text()) for p in eng.glob('*/receipt.json')]
summary={'schema':'walker-k1-1-publication-validation-v1','scientific_result_commit':'6ae18cd1d0d846d000a4d44929a25d0316bef75c','clean_export_commit':'a2ccbc86d44027efbaf1496f7e42c1fd57a3cb03','tests':{'passed':707,'skipped':1,'xfailed':1},'clean_export_commands':26,'capsule_files_verified':2650,'historical_files_verified':162,'maintained_links_verified':911,'numeric_report_fields_checked':52,'final_fixture_polish':'A same-size tamper fixture now uses a seven-byte expected payload; its three focused tests pass after the exported implementation. No implementation changed after the successful export.','scientific_reruns':0,'previous_failed_export':'022 passed all704 tests and all26commands; every output hash/size matched, but an unresolved /var versus /private/var base alias caused false containment rejection. Failure retained; canonical base fix separately tested.','previous_failed_text_check':'019 stopped on typographic minus versus ASCII minus. Both checker sources retained; corrected formatting check020 passed52 comparisons without changing report values.','metered_command_wall_seconds_sum_through_snapshot':sum(v['wall_seconds'] for v in known),'sum_scope':'Includes enclosing test/audit/report subprocess wall times; do not add their internal times again or interpret the sum as elapsed investigation time. Uninstrumented editing, global synthetic-test arithmetic/physics counts, billing/energy are unknown.','full_append_only_engineering_location':str(eng),'later_overhead':'This bundle closes before its own commit/push. Subsequent publication/remote verification/CI receipts remain append-only at that explicit external artifact location; frozen capsule and this snapshot are not rewritten.','files':files}
(dest/'receipt.json').write_text(json.dumps(summary,indent=2)+'\n')
readme='''# K1.1 publication validation\n\nThe saved-only scientific result and its immutable capsule were committed as `6ae18cd`. The successful clean Git export of `a2ccbc8` contains no ignored runs/artifacts and passes **707 tests, one skip and the existing expected failure**, all 26 CLI/inspection/report commands, 2,650 capsule bindings, 162 historical files and 911 maintained links. Ruff checks 191 active files. No scientific worker reran.\n\nThe export verifies and renders the new capsule as well as all older studies. It also checks regenerated output bytes against their own report receipts, so legitimate new PDF timestamp metadata is not confused with original frozen PDF bytes. The complete source/input/worker closure was independently verified by [audit002](../../../results/trajectory_review_k1_1/audit_002/receipt.json).\n\n- [Validation census and exact file hashes](receipt.json).\n- [Successful export command/elapsed receipt](commands/025_final_export_validation/receipt.json), [stdout](commands/025_final_export_validation/stdout.txt), [stderr](commands/025_final_export_validation/stderr.txt).\n- [Previous failed export](commands/022_results_export_validation/receipt.json): all704 tests and all26 commands passed; the final containment check miscompared macOS `/var` and `/private/var` aliases. Every output size/hash matched. The canonical-base correction has alias, escaped-symlink and changed-byte regression checks.\n- [Final fixture consistency checks](commands/026_export_fixture_consistency/receipt.json): three focused checks pass after using a seven-byte expected payload in the same-size tamper test. This only changes a test literal.\n- [52 maintained-report numeric checks](checks/report_number_verification.json). The first formatting checker stopped at a Unicode minus; both checker versions and failed/passed commands are retained, without changed scientific values.\n- [Obsidian update receipt](checks/obsidian_update.json): three existing notes updated, four-note structure retained, exact backups outside the vault, original user scratch text and Research Thoughts preserved. No new notes or result tables were added.\n\nThe [scientific capsule accounting](../../../results/trajectory_review_k1_1/accounting/accounting.json) separates inherited K1 counters, new zero-model/physics arithmetic, failed/passed audits and both reports. This later bundle retains publication/export/check overhead, including failures. Command wall times include their subprocesses and must not be added to those internal times. Global synthetic-fixture arithmetic/physics counts and uninstrumented editing/tool billing are unknown, not zero. No efficiency claim is made.\n\nThis snapshot precedes its own commit/push. Later append-only publication, remote-verification and CI receipts remain at the explicitly located `artifacts/2026-11-01_trajectory_review_k1_1_001/engineering` outside Git. They do not change the frozen run, capsule, or scientific conclusion.\n'''
(dest/'README.md').write_text(readme)
print(json.dumps({'directory':str(dest),'copied_files':len(files),'copied_bytes':sum(v['bytes'] for v in files.values()),'known_command_seconds':summary['metered_command_wall_seconds_sum_through_snapshot']}))
